// Project board — this app's MCP server. Centralu starts it (`node server.mjs`, stdio) when it is first
// needed and restarts it after the builder's turn when this folder changed.
// This file only registers the tools; each family lives in its own `*-tools.mjs` beside it (AGENTS.md,
// "Files"). Edit those, github.mjs and ui/index.html freely. Never edit runtime/ (generated by Centralu).
// Read AGENTS.md for the rules.
//
// The board is the GitHub Project named in project.json. GitHub is the only copy: every read asks
// GitHub (through the person's own `gh`, see github.mjs), with an in-memory cache of a few seconds,
// and every write goes straight to GitHub and is read back before the tool answers.
import { McpServer, serveStdio, centralu } from './runtime/centralu-app-runtime.mjs'
import { tools as boardTools } from './board-tools.mjs'
import { tools as ciTools } from './ci-tools.mjs'
import { tools as contributeTools } from './contribute-tools.mjs'
import { tools as decisionTools } from './decision-tools.mjs'
import { tools as helpTools } from './help-tools.mjs'
import { startQueue, tools as queueTools } from './queue-tools.mjs'
import { tools as readerTools } from './reader-tools.mjs'
import { tools as releaseTools } from './release-tools.mjs'
import { UI, VIEW_CSP, tools as viewTools, viewResource } from './view-tools.mjs'
import { tools as wordsTools } from './words-tools.mjs'

const TOOLS = { ...viewTools, ...readerTools, ...ciTools, ...helpTools, ...queueTools, ...decisionTools, ...contributeTools, ...releaseTools, ...wordsTools, ...boardTools }

/** The order agents and the screen list the tools in, as it was before the tools moved into families. */
const ORDER = [
  'show',
  'read_item',
  'read_discussion',
  'read_failed_job',
  'save_answer',
  'list_owner_answers',
  'mark_answer_recorded',
  'comment',
  'edit_comment',
  'file_issue',
  'open_pr',
  'commit_check',
  'rebase_stack',
  'release_status',
  'release',
  'private_words',
  'edit_private_words',
  'list_items',
  'get_items',
  'set_item_fields',
  'add_item',
  'ci_status',
  'merge_when_green',
  'mark_ready',
  'help',
  'queue_merge',
  'integrate',
  'merge_queue',
  'unqueue',
  'ack',
]
const unlisted = Object.keys(TOOLS).filter((name) => !ORDER.includes(name))
if (unlisted.length) throw new Error(`server.mjs: add ${unlisted.join(', ')} to ORDER`)

serveStdio(() => {
  const server = new McpServer({ name: 'project-board', version: '0.3.0' }, { capabilities: { tools: {}, resources: {} } })

  viewResource(server, 'board', UI, new URL('./ui/index.html', import.meta.url), { ui: { csp: VIEW_CSP } })

  for (const name of ORDER) centralu.tool(server, name, TOOLS[name].config, TOOLS[name].handler)

  return server
})

// The merge queue carries on in this server, which stays running while the queue has work (queue-driver.mjs queueBusy)
startQueue()
